import { Controller, Get, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

// 가정: 연령분석 구간 경계(일). 0~30, 31~60, 61~90, 91일 이상
const AGING_DAYS = [30, 60, 90];
const AGING_LABELS = ['30일 이내', '31~60일', '61~90일', '91일 이상'];
const DEFAULT_SIZE = 20;
const MAX_SIZE = 200;

function text(v: unknown): string {
  return v === undefined || v === null ? '' : String(v).trim();
}

function requiredDate(v: unknown): string {
  const s = text(v);
  if (!/^\d{4}-\d{2}-\d{2}$/.test(s)) {
    throw new ApiError(400, 'VALIDATION_FAILED', '조회 기간을 YYYY-MM-DD 형식으로 입력해 주세요.');
  }
  return s;
}

function optionalId(v: unknown): string | null {
  const s = text(v);
  if (s === '') {
    return null;
  }
  if (!/^\d+$/.test(s)) {
    throw new ApiError(400, 'VALIDATION_FAILED', '조건 값은 숫자여야 합니다.');
  }
  return s;
}

function intOf(v: unknown, fallback: number): number {
  const s = text(v);
  if (s === '') {
    return fallback;
  }
  if (!/^\d+$/.test(s)) {
    throw new ApiError(400, 'VALIDATION_FAILED', '페이지 값은 숫자여야 합니다.');
  }
  return Number(s);
}

const FROM_SQL = `
  FROM voucher_line vl
  JOIN journal_voucher jv ON jv.journal_voucher_id = vl.journal_voucher_id
  JOIN account_item ai ON ai.account_item_id = vl.account_item_id
  LEFT JOIN partner p ON p.partner_id = vl.partner_id
  LEFT JOIN LATERAL (
    SELECT b.processing_type
    FROM bank_transaction b
    WHERE b.journal_voucher_id = jv.journal_voucher_id
    ORDER BY b.bank_transaction_id
    LIMIT 1
  ) bt ON true
  WHERE jv.voucher_date BETWEEN CAST(:fromDate AS date) AND CAST(:toDate AS date)
    AND (CAST(:accountItemId AS bigint) IS NULL OR vl.account_item_id = CAST(:accountItemId AS bigint))
    AND (CAST(:partnerId AS bigint) IS NULL OR vl.partner_id = CAST(:partnerId AS bigint))
`;

@Controller('api/v1')
export class FnSfr00809Controller {
  @Get('/voucher-clearings')
  async listVoucherClearings(@Req() req: Request) {
    const user = currentUser(req);
    user.require('예산·회계 담당자');
    const query = checks.queryOf(req.query);
    const fromDate = requiredDate(query['fromDate']);
    const toDate = requiredDate(query['toDate']);
    const accountItemId = optionalId(query['accountItemId']);
    const partnerId = optionalId(query['partnerId']);
    const page = intOf(query['page'], 0);
    const size = Math.min(Math.max(intOf(query['size'], DEFAULT_SIZE), 1), MAX_SIZE);
    return transaction(async (db) => {
      const check = await db.query(
        'SELECT CAST(:fromDate AS date) > CAST(:toDate AS date) AS "invalid"',
        { fromDate, toDate },
      );
      if (check[0] && check[0]['invalid'] === true) {
        throw new ApiError(422, 'INVALID_DATE_RANGE', '조회 시작일이 종료일보다 늦을 수 없습니다.');
      }
      const filter = { fromDate, toDate, accountItemId, partnerId };
      const totalRows = await db.query('SELECT COUNT(*) AS "total" ' + FROM_SQL, filter);
      const total = Number(totalRows[0]?.['total'] ?? 0);
      const rows = await db.query(
        `SELECT jv.voucher_no AS "voucherNo",
          jv.voucher_date AS "voucherDate",
          vl.account_item_id AS "accountItemId",
          ai.account_name AS "accountName",
          p.partner_name AS "partnerName",
          vl.amount AS "amount",
          COALESCE(bt.processing_type, '미처리') AS "processingType"
        ${FROM_SQL}
        ORDER BY jv.voucher_date DESC, jv.journal_voucher_id DESC, vl.line_no
        LIMIT CAST(:size AS integer) OFFSET CAST(:offset AS integer)`,
        { ...filter, size, offset: page * size },
      );
      // 가정: 반제되지 않은 분개 금액을 전표일자 기준 경과일 구간별로 계정마다 집계
      const agingRows = await db.query(
        `SELECT vl.account_item_id AS "accountItemId",
          CASE WHEN CURRENT_DATE - jv.voucher_date <= CAST(:d1 AS integer) THEN 0
               WHEN CURRENT_DATE - jv.voucher_date <= CAST(:d2 AS integer) THEN 1
               WHEN CURRENT_DATE - jv.voucher_date <= CAST(:d3 AS integer) THEN 2
               ELSE 3 END AS "bucket",
          SUM(vl.amount) AS "amount"
        ${FROM_SQL}
          AND COALESCE(bt.processing_type, '미처리') <> '반제'
        GROUP BY vl.account_item_id, 2`,
        { ...filter, d1: AGING_DAYS[0], d2: AGING_DAYS[1], d3: AGING_DAYS[2] },
      );
      const aging = new Map<string, number[]>();
      for (const a of agingRows) {
        const key = String(a['accountItemId']);
        const sums = aging.get(key) ?? [0, 0, 0, 0];
        sums[Number(a['bucket'])] = Number(a['amount']);
        aging.set(key, sums);
      }
      const items = rows.map((r) => {
        const sums = aging.get(String(r['accountItemId'])) ?? [0, 0, 0, 0];
        return {
          voucherNo: r['voucherNo'],
          voucherDate: r['voucherDate'],
          accountName: r['accountName'],
          partnerName: r['partnerName'],
          amount: Number(r['amount']),
          processingType: r['processingType'],
          agingBuckets: AGING_LABELS.map((label, i) => ({ label, amount: sums[i] })),
        };
      });
      return { items, page, size, total };
    });
  }
}

