import { useState } from 'react';
import {
  call,
  useData,
  Badge,
  Num,
  DateText,
  Filters,
  Band,
  DataTable,
  Pager,
  Drawer,
  Pairs,
  Tiles,
  Field,
  DateInput,
  LookupSelect,
  ErrorText,
} from '../kit';
import type { PageProps, Row, Page } from '../kit';

interface Bucket {
  label: string;
  amount: number;
}

export default function FnSfr00809Page({ role, notify }: PageProps) {
  const [fromDate, setFromDate] = useState('');
  const [toDate, setToDate] = useState('');
  const [accountItemId, setAccountItemId] = useState<number | string>('');
  const [partnerId, setPartnerId] = useState<number | string>('');
  const [applied, setApplied] = useState<Row | null>(null);
  const [pageNo, setPageNo] = useState(0);
  const [selected, setSelected] = useState<Row | null>(null);
  const [formError, setFormError] = useState('');

  const { data, error, loading } = useData<Page>(async () => {
    if (!applied) {
      return { items: [], page: 0, size: 20, total: 0 };
    }
    return call<Page>('GET', '/voucher-clearings', role, undefined, { ...applied, page: pageNo });
  }, [applied, pageNo, role]);

  const rows = data?.items ?? [];

  function search() {
    if (!fromDate || !toDate) {
      setFormError('조회 시작일과 종료일을 입력해 주세요.');
      return;
    }
    setFormError('');
    setPageNo(0);
    setApplied({ fromDate, toDate, accountItemId, partnerId });
    notify('조회했습니다.');
  }

  function reset() {
    setFromDate('');
    setToDate('');
    setAccountItemId('');
    setPartnerId('');
    setApplied(null);
    setPageNo(0);
    setFormError('');
  }

  const unclearedCount = rows.filter((r) => r['processingType'] !== '반제').length;

  const agingByAccount = new Map<string, Bucket[]>();
  for (const r of rows) {
    agingByAccount.set(String(r['accountName']), r['agingBuckets'] as Bucket[]);
  }

  return (
    <div className="bento">
      <section className="box span-4">
        <h2>조회 건수</h2>
        <Tiles items={[['전체', <Num value={data?.total ?? 0} />]]} />
      </section>
      <section className="box span-4">
        <h2>미반제 건수</h2>
        <Tiles items={[['현재 쪽', <Num value={unclearedCount} />]]} />
      </section>
      <section className="box span-4">
        <h2>반제 완료</h2>
        <Tiles items={[['현재 쪽', <Num value={rows.length - unclearedCount} />]]} />
      </section>
      <section className="box span-8">
        <h2>반제처리 현황</h2>
        <Filters onSearch={search} onReset={reset}>
          <Field label="조회 시작일" required>
            <DateInput value={fromDate} onChange={setFromDate} />
          </Field>
          <Field label="조회 종료일" required>
            <DateInput value={toDate} onChange={setToDate} />
          </Field>
          <Field label="반제 기준 계정과목">
            <LookupSelect table="account_item" role={role} value={accountItemId} onChange={setAccountItemId} />
          </Field>
          <Field label="거래처 조건">
            <LookupSelect table="partner" role={role} value={partnerId} onChange={setPartnerId} />
          </Field>
        </Filters>
        {formError && <ErrorText text={formError} />}
        {error && <ErrorText text={error} />}
        <Band total={data?.total} />
        <DataTable
          columns={[
            { key: 'voucherNo', label: '전표번호' },
            { key: 'voucherDate', label: '전표일자', render: (r) => <DateText value={r['voucherDate']} /> },
            { key: 'accountName', label: '계정과목 명칭' },
            { key: 'partnerName', label: '거래처 명칭' },
            { key: 'amount', label: '금액', render: (r) => <Num value={r['amount']} /> },
            { key: 'processingType', label: '반제 상태', render: (r) => <Badge value={r['processingType']} /> },
          ]}
          rows={rows}
          onRowClick={(r) => setSelected(r)}
          empty={loading ? '불러오는 중입니다.' : '조회 조건을 입력하고 조회해 주세요.'}
        />
        <Pager page={data?.page ?? 0} size={data?.size ?? 20} total={data?.total ?? 0} onPage={setPageNo} />
      </section>
      <section className="box span-4">
        <h2>계정별 연령분석</h2>
        {agingByAccount.size === 0 && <p>조회된 내역이 없습니다.</p>}
        {Array.from(agingByAccount.entries()).map(([name, buckets]) => (
          <Pairs
            key={name}
            items={[
              ['계정과목', name],
              ...buckets.map((b): [string, JSX.Element] => [b.label, <Num value={b.amount} />]),
            ]}
          />
        ))}
      </section>
      {selected && (
        <Drawer title="전표 반제 상세" onClose={() => setSelected(null)}>
          <Pairs
            items={[
              ['전표번호', String(selected['voucherNo'] ?? '')],
              ['전표일자', <DateText value={selected['voucherDate']} />],
              ['계정과목 명칭', String(selected['accountName'] ?? '')],
              ['거래처 명칭', String(selected['partnerName'] ?? '')],
              ['금액', <Num value={selected['amount']} />],
              ['반제 상태', <Badge value={selected['processingType']} />],
              ...((selected['agingBuckets'] as Bucket[]) ?? []).map((b): [string, JSX.Element] => [
                '연령분석 ' + b.label,
                <Num value={b.amount} />,
              ]),
            ]}
          />
        </Drawer>
      )}
    </div>
  );
}
